CREATE TABLE IF NOT EXISTS cars (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, make TEXT, model TEXT, year INTEGER, price INTEGER, mileage INTEGER, fuel TEXT, power_kw INTEGER, engine TEXT, transmission TEXT, euro_class TEXT, color TEXT, seats INTEGER, description TEXT, options_json TEXT NOT NULL DEFAULT '[]', images_json TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL DEFAULT 'available', featured INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);